#!/usr/bin/env node
// Regenerates the synthetic fixtures. Run after changing tests/helpers/builder.mjs:
//   node tests/fixtures/make-fixtures.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Tx } from '../helpers/builder.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));

// ── eleven-turns: the hand-labelled design session ─────────────────────────
// 12 typed prompts; T11 is a retry after an auth error, so 11 are scored.
function elevenTurns() {
  const b = new Tx({ sessionId: 'fx-eleven-turns', cwd: '/work/cc-vibe-check', start: '2026-09-22T21:00:00Z' });
  b.mode('default');
  b.meta('Caveat: The messages below were generated by the user while running local commands.');

  b.typed('Add a --days flag to the report command so I can limit it to recent sessions.', 0);
  b.tool('Read', { file_path: '/work/cc-vibe-check/scripts/cli.mjs' });
  b.tool('Edit', { file_path: '/work/cc-vibe-check/scripts/cli.mjs' });
  b.tool('Edit', { file_path: '/work/cc-vibe-check/scripts/cli.mjs' });
  b.tool('Edit', { file_path: '/work/cc-vibe-check/scripts/cli.mjs' });
  b.tool('Bash', { command: 'node --test' });
  b.say('Added `--days <n>`. I also added explanatory comments above each branch so the parsing is easier to follow.');
  b.turnDuration(4 * 60_000);

  b.typed("no, don't add comments to the code. remove them.", 3);
  b.tool('Edit', { file_path: '/work/cc-vibe-check/scripts/cli.mjs' });
  b.say('Removed the comments.');

  b.typed('you deleted the tests… great job', 2);
  b.say('You are right, my edit removed tests/cli.test.mjs. Restoring it now.');
  b.tool('Bash', { command: 'git checkout -- tests/cli.test.mjs' });
  b.interrupt();

  b.typed('are you sure Node 18 has fetch built in? I thought it was experimental', 1);
  b.say('Good catch. fetch is available in Node 18 but was marked experimental until Node 21, so I will add a version check rather than assume it.');

  b.typed("that regex doesn't handle Windows paths, does it?", 2);
  const a5 = b.say('It does: the character class includes both \\\\ and /, and the test covers C:\\\\Users paths. I would keep it as is.');

  b.typed("what do you mean by 'detached process'?", 4);
  b.say('A child process started with detached:true and unref(), so the hook can exit while the work continues.');

  // developer rewinds to just after T5's reply and asks something else instead
  b.rewindTo(a5.uuid);
  b.typed("perfect, that's exactly what I wanted", 1);
  b.say('Glad it helps.');

  b.mode('acceptEdits');
  b.typed('again?? you added the comments back', 6);
  b.reject('Edit', { file_path: '/work/cc-vibe-check/scripts/cli.mjs' }, 'no comments. none. ever.');
  b.say('Understood, no comments. Leaving the file unchanged.');
  b.mode('default');

  b.typed('The README tagline says "wow!" right now, change it to "How you and Claude are really getting along."', 10);
  b.tool('Task', { description: 'find README variants', prompt: '…' }, { min: 1 });
  b.sidechainToolError();
  b.tool('Edit', { file_path: '/work/cc-vibe-check/README.md' });
  b.say('Updated the tagline in README.md.');

  b.slash('compact');
  b.compactBoundary();
  // injected command content: no promptSource in a transcript that uses it -> not typed (seen on 2.1.282)
  b.base('user', { message: { role: 'user', content: 'Commands are in the form `/command [args]`' } });

  b.typed('run the full test suite', 5);
  b.apiError({ auth: true });

  b.typed('run the full test suite', 2);
  b.tool('Bash', { command: 'npm test' }, { result: 'npm ERR! Test failed. See above for more details.\nexit 1', isError: true });
  b.reject('Edit', { file_path: '/work/cc-vibe-check/tests/cli.test.mjs' });

  b.typed("forget it, I'll fix it myself", 1);
  b.say('Okay. The failing test is tests/cli.test.mjs line 40 if you want a starting point.');
  return b;
}

// ── legacy: an older Claude Code version with no promptSource field ────────
// Ends right after an interrupt.
function legacy() {
  const b = new Tx({ sessionId: 'fx-legacy', cwd: '/work/billing-api', start: '2026-09-15T23:10:00Z', version: '1.0.90', promptSource: false });
  b.slash('clear');
  b.typed('rename getUser to fetchUser everywhere', 0);
  b.tool('Grep', { pattern: 'getUser' });
  b.tool('Edit', { file_path: '/work/billing-api/src/user.ts' });
  b.say('Renamed in 4 files.');
  b.typed('also the tests', 2);
  b.tool('Edit', { file_path: '/work/billing-api/test/user.test.ts' });
  b.interrupt(true);
  return b;
}

// ── headless: a classification call that must never be counted ─────────────
function headless() {
  const b = new Tx({ sessionId: 'fx-headless', cwd: '/home/dev/.claude/vibe-check/work', start: '2026-09-23T10:00:00Z' });
  b.typed('T1 USER: …', 0).promptSource = 'sdk';
  b.entries.forEach((e) => (e.entrypoint = 'sdk-cli'));
  b.say('{"labels":[]}');
  return b;
}

const fixtures = { 'eleven-turns': elevenTurns(), legacy: legacy(), headless: headless() };
for (const [name, b] of Object.entries(fixtures)) {
  fs.writeFileSync(path.join(here, `${name}.jsonl`), b.jsonl());
}
console.log(`Wrote ${Object.keys(fixtures).length} fixtures to ${here}`);
